[SPECIALIST_FINDING]
{
  "specialty": "kdoctor-cardiology",
  "answer": "3개월간 지속된 1족지(엄지발가락) 허혈성 궤양 의심 + 족배동맥 맥박 감소 + 흡연력 + 조기 관상동맥질환 가족력은 만성하지위험허혈(CLTI, critical limb-threatening ischemia) 가능성을 시사하며, 이는 시간 민감 상황이다. 원격 텍스트만으로는 ABI/TBI/도플러/CTA 소견을 확인할 수 없으므로, 응급도 판정은 임상적 맥락(휴식통·야간통·감염·조직 결손 진행 속도)에 근거해 '24시간 내 혈관외과/순환기 평가'로 제안한다. 항혈소판/스타틴은 적응이 강하게 고려되지만 개시·용량은 대면 진료에서 결정되어야 한다.",
  "red_flag": {
    "present": true,
    "items": [
      { "id": "CLTI_suspected", "evidence": "3개월 지속 1족지 허혈성 궤양 의심 + 족배동맥 맥박 감소 + 흡연력", "basis": "history" },
      { "id": "R-ischemia", "evidence": "조직 결손(궤양)이 이미 존재하는데도 3개월간 진행 — 감염·골수염 동반 가능성 배제 안 됨", "basis": "history" },
      { "id": "infection_risk", "evidence": "당뇨 여부 미확인. 궤양 감염 시 패혈증·절단 위험 급상승", "basis": "history" }
    ]
  },
  "hypotheses": [
    {
      "name": "만성하지위험허혈(CLTI) / 말초동맥질환(PAD) 진행",
      "icd10": "I70.2 계열",
      "must_not_miss": true,
      "probability_band": "high",
      "supports": [
        { "text": "1족지 허혈성 궤양 3개월 지속", "basis": "history" },
        { "text": "족배동맥 맥박 감소", "basis": "history" },
        { "text": "흡연력", "basis": "history" },
        { "text": "64세(3개월 전 68세) 남성, 부친 조기 심근경색 가족력", "basis": "history" }
      ],
      "against": [
        { "text": "ABI/TBI/도플러/CTA 결과 미확인 — 폐쇄 부위·범위·다혈관 여부 모름", "basis": "history" }
      ]
    },
    {
      "name": "당뇨병성 족부 궤양(신경병증·감염 중심)",
      "icd10": "E11.5 / E10.5",
      "must_not_miss": true,
      "probability_band": "medium",
      "supports": [
        { "text": "1족지 궤양 — 당뇨병성 족부 궤양의 흔한 위치", "basis": "history" }
      ],
      "against": [
        { "text": "족배동맥 맥박 감소는 신경병증 단독보다는 동맥 허혈을 시사", "basis": "history" },
