      "name": "감염성/골수염 동반",
      "icd10": "M86.0 / L08.9",
      "must_not_miss": true,
      "probability_band": "medium",
      "supports": [
        { "text": "3개월간 지속된 궤양 — 만성 창상 감염 위험", "basis": "history" }
      ],
      "against": [
        { "text": "발열·삼출·주위 염증 소견 미확인", "basis": "history" }
